import React, { useState } from "react";
import { FcLike } from "react-icons/fc";

const Card = ({ course }) => {
  const [liked, setLiked] = useState(false);

  return (
    <div>
      <img src={course.image.url} alt={course.title} />

      <button onClick={() => setLiked(!liked)}>
        {liked ? "❤️" : "🤍"}
      </button>
    </div>
  );
};

export default Card;
